	                            img.style.margin = '0.5em 0';
	                            img.setAttribute('v:shapes', 'image' + Math.random().toString(36).substr(2, 9));
	                            img.alt = 'STL 3D Model';
	                            
	                            container.parentNode.replaceChild(img, container);
